// MAIN //

/**
* Evaluates the base 2 exponential function.
*
* @param {number} x - input value
* @returns {number} function value
*
* @example
* var v = exp2( 3.0 );
* // returns 8.0
*
* @example
* var v = exp2( -9.0 );
* // returns ~0.002
*
* @example
* var v = exp2( 0.0 );
* // returns 1.0
*
* @example
* var v = exp2( NaN );
* // returns NaN
*/
function exp2(x) {
	var twopk;
	var hx = getHighWord(x);
	var lx;
	var i0;
	var ix = hx & 0x7fffffff;
	var k;
	var t;
	var z;
	var r;

	if (ix >= 0x40900000) { // |x| >= 1024
		if (ix >= 0x7ff00000) { // |x| >= Inf
			lx = getLowWord(x);
			if (((ix & 0xfffff) | lx) !== 0 || (hx & 0x80000000) === 0) {
				return x + x; // NaN or +Inf
			}
			return 0.0; // -Inf
		}
		if (x >= 1024.0) {
			return Number.POSITIVE_INFINITY; // overflow
		}
		if (x <= -1075.0) {
			return 0.0; // underflow
		}
	} else if (ix < 0x3c900000) { // |x| < 2^-54
		return 1.0 + x;
	}
	// Reduce x, computing z, i0, and k...
	t = (x * TBLSIZE) + REDUX;
	i0 = getLowWord(t);
	k = (i0 >> TBLBITS) << 20;
	i0 = (i0 & (TBLSIZE - 1)) << 1;
	t -= REDUX;
	t /= TBLSIZE;
	z = x - t;

	// Compute r = exp2(y) = exp2t[i0] * p(z - eps[i])...
	t = TBL[i0];      // exp2t[i0]
	z -= TBL[i0 + 1]; // eps[i0]

	if (k >= -1070596096) { // k >= -(1021 << 20)
		twopk = setHighWord(0.0, (BIAS << 20) + k);
	} else {
		twopk = setHighWord(0.0, ((BIAS + 1000) << 20) + k);
	}

	// Pade approximation...
	r = t + (t * z * (P1 + (z * (P2 + (z * (P3 + (z * (P4 + (z * P5)))))))));

	// Scale by 2**(k>>20)...
	if (k >= -1070596096) { // k >= -(1021 << 20)
		if (k === 1073741824) { // k == 1024 << 20
			return r * 2.0 * 8.98846567431158e307; // 0x1p1023
		}
		// eslint-disable-next-line @cspell/spellchecker
		return r * twopk; // twopk is 2^k
	}
	// eslint-disable-next-line @cspell/spellchecker
	return r * twopk * 9.332636185032189e-302; // twom1000
}


// EXPORTS //

module.exports = exp2;
